-- +goose StatementBegin
-- 1. Сценарии 1 и 2
INSERT INTO scenarios (id, title, description, icon, role, difficulty, required_scenarios_this_level, start_node_id)
VALUES
    (1, 'Продажа умного пиксельного дисплея', 'Вы продаете свой умный пиксельный дисплей Divoom Pixoo 64. Вы выложили объявление буквально 15 минут назад, и вам уже написал первый заинтересованный покупатель.', 'monitor', 'seller', 'easy', 0, NULL),
    (2, 'Продажа графического планшета', 'Вы выложили объявление о продаже своего графического планшета. Вскоре появляется покупатель, который сразу оформляет заказ, после чего в чате возникает сообщение от службы поддержки.', 'tablet', 'seller', 'hard', 0, NULL)
    ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title,
                            description = EXCLUDED.description,
                            icon = EXCLUDED.icon,
                            role = EXCLUDED.role,
                            difficulty = EXCLUDED.difficulty;

-- 2. Сценарии 3 и 4
INSERT INTO scenarios (id, title, description, icon, role, difficulty, required_scenarios_this_level, start_node_id)
VALUES
    (3, 'Покупка умной колонки', 'Вы нашли объявление о продаже новой умной колонки по очень привлекательной цене. Вы пишете продавцу, чтобы убедиться, что товар в наличии, и перейти к оформлению покупки.', 'speaker', 'buyer', 'easy', 0, NULL),
    (4, 'Покупка гравийного велосипеда', 'Вы нашли отличный гравийный велосипед по привлекательной цене в соседнем регионе. Продавец охотно отвечает на вопросы, подтверждает идеальное состояние байка и готов отправлять его курьерской доставкой.', 'bike', 'buyer', 'hard', 0, NULL)
    ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title,
                            description = EXCLUDED.description,
                            icon = EXCLUDED.icon,
                            role = EXCLUDED.role,
                            difficulty = EXCLUDED.difficulty;

-- Очистка старых зависимостей перед пересозданием узлов
UPDATE scenarios SET start_node_id = NULL WHERE id IN (1, 2, 3, 4);
DELETE FROM scenario_options WHERE from_node_id IN (SELECT id FROM scenario_nodes WHERE scenario_id IN (1, 2, 3, 4));
DELETE FROM scenario_nodes WHERE scenario_id IN (1, 2, 3, 4);

-- Вставка узлов (Nodes)
INSERT INTO scenario_nodes (id, scenario_id, message_text, is_final, final_status)
VALUES
    -- Сценарий 1
    (1, 1, 'Добрый день! Очень давно искал именно эту модель, хочу настроить кастомные анимации и циклы. Состояние рабочее? Готов сейчас же оформить доставку.', FALSE, NULL),
    (2, 1, 'Отлично, я всё оплатил! Только система почему-то просит указать email продавца, чтобы выслать вам электронный чек и гарантийный талон для курьера. Напишите вашу почту?', FALSE, NULL),
    (3, 1, 'Спасибо! Вам на почту только что должно было прийти письмо от техподдержки с кнопкой "Получить средства". Нажмите её и подтвердите заказ, а то у меня деньги уже списались и висят в холде! Жду 🙏', FALSE, NULL),
    (4, 1, 'Диалог завершен. Вы отказались от доставки. Попробуйте пройти сценарий заново, чтобы отработать механику безопасной доставки.', TRUE, 'red'),
    (5, 1, 'Мошенник сливается. Вы не поддались на уловку со сбором личных данных и сохранили диалог внутри платформы.', TRUE, 'green'),
    (6, 1, 'Передача email-адреса в чате — первый шаг к потере денег. Хорошо, что вы вовремя остановились и не стали открывать фальшивое письмо!', TRUE, 'yellow'),
    (7, 1, 'Вы перешли на поддельный сайт. В похожей ситуации пользователи платформы теряли деньги, вводя данные своей карты на фишинговом ресурсе.', TRUE, 'red'),

    -- Сценарий 2
    (8, 2, 'Здравствуйте! Меня зовут Анна, я сотрудник службы поддержки Avito. Ваш покупатель уже оплатил заказ, но чтобы система оформила выдачу товара и перевела деньги вам, нужно подтвердить, что аккаунт продавца настоящий. Сейчас вам придёт смс с кодом — продиктуйте его мне, пожалуйста.', FALSE, NULL),
    (9, 2, 'Наша система иногда не успевает обновиться сразу, поэтому просто перейдите по ссылке для продавцов и подтвердите операцию вручную — это займёт минуту: avito-partners-verify.ru', FALSE, NULL),
    (10, 2, 'Ясно. Тогда для подтверждения личности продавца вам придётся позвонить в наш контактный центр по номеру +7 900 123-45-67 — оператор во время звонка попросит продиктовать код, который придёт вам по смс для сверки, иначе заказ отменят, а вас заблокируют за подозрительную активность.', FALSE, NULL),
    (11, 2, 'Вы продиктовали код из смс по телефону. Мошенники получили доступ к аккаунту и деньгам, хотя вы отказались от кода в чате и от фишинговой ссылки на предыдущих шагах.', TRUE, 'red'),
    (12, 2, 'Вы передали код мошеннику на первом же шаге. Аккаунт или деньги были скомпрометированы немедленно.', TRUE, 'red'),
    (13, 2, 'Вы ввели данные на поддельной странице. Аккаунт продавца скомпрометирован.', TRUE, 'red'),
    (14, 2, 'Вы не поддались ни на код, ни на ссылку, ни на звонок с угрозой блокировки. Все три попытки мошенника провалились.', TRUE, 'green'),

    -- Сценарий 3
    (15, 3, 'Здравствуйте! Да, колонка в наличии, состояние отличное. Но на официальной странице сейчас сбой системы и ошибка с ценой — покупайте через нашу защищенную партнерскую ссылку, там применилась скидка: avito-shop-sale.com/item482. В самом приложении цена уже не обновится.', FALSE, NULL),
    (16, 3, 'Слушайте, раз вы не хотите переходить по ссылке, давайте проще: я отправлю вам трек-номер и скриншот подтверждения, а вы переведете деньги напрямую мне на карту, и я сразу отправлю колонку курьером.', FALSE, NULL),
    (17, 3, 'Да поймите, мне самому не выгодно терять время на пустые споры с поддержкой! Если не хотите на карту, я могу вызвать курьера Яндекс.Доставки — он сам заберет деньги наличными у вас дома.', FALSE, NULL),
    (18, 3, 'Последний шанс: курьер уже у дверей моего пункта выдачи, но для активации отправки вам нужно лишь подтвердить нулевой платеж (для проверки карты) на странице службы: courier-express-secure.ru/pay', FALSE, NULL),
    (19, 3, 'Вы проявили выдержку и отказались от всех сомнительных схем. Покупка оформлена безопасно через приложение.', TRUE, 'green'),
    (20, 3, 'Вы перевели деньги напрямую на карту незнакомцу. Продавец перестал выходить на связь, вернуть средства не удалось.', TRUE, 'red'),
    (21, 3, 'Вы согласились передать наличные курьеру без официального оформления через платформу. Товар вы не получили, деньги потеряны.', TRUE, 'red'),
    (22, 3, 'Вы ввели данные карты на фишинговом сайте курьерской службы. Все сбережения были списаны мошенниками.', TRUE, 'red'),
    (23, 3, 'Вы вовремя распознали обман на финальном этапе и отказались от платежа. Деньги и карта остались в безопасности.', TRUE, 'green'),

    -- Сценарий 4
    (24, 4, 'Здравствуйте! Да, велосипед в наличии, трансмиссия Shimano GRX настроена. Из-за габаритов байка я всегда оформляю специальную обрешетку через сервис «СпецБайк», чтобы ничего не погнулось. Вот защищенная страница отправки: specbike-logistics.ru. Оформляем там или вам привычнее через платформу?', FALSE, NULL),
    (25, 4, 'Хорошо, давайте через приложение, раз вам так спокойнее! Но курьер сможет забрать байк только послезавтра. Я на всякий случай зарезервировал жесткий бокс в «СпецБайк», вот прямая ссылка на него, вдруг решите передумать и ускорить отправку: specbike-logistics.ru/box392', FALSE, NULL),
    (26, 4, 'Слушайте, поддержка приложения только что отклонила стандартную заявку из-за превышения габаритов рамы! Они пишут, что без нашего «СпецБайка» отправить не выйдет. Придется все-таки оформлять через них, иначе сделку отменят.', FALSE, NULL),
    (27, 4, 'Ладно, раз вы принципиально против сторонних сайтов, я нашел другой выход: давайте я отправлю транспортной компанией напрямую, а вы мне скинете предоплату за пересылку на карту, чтобы я не рисковал своими деньгами?', FALSE, NULL),
    (28, 4, 'Послушайте, я уже стою у пункта приема! Если вы сейчас же не подтвердите заявку на странице логистики и не оплатите 350 рублей за сборку бокса, курьер уедет, а я напишу на вас жалобу за срыв сделки!', FALSE, NULL),
    (29, 4, 'Вы проявили стойкость, отказались от всех сомнительных ссылок и настояли на правилах площадки. Сделка прошла безопасно.', TRUE, 'green'),
    (30, 4, 'Вы не поддались на уговоры перейти на сторонний логистический сайт. Отличная бдительность.', TRUE, 'green'),
    (31, 4, 'Сохраненная ссылка на сторонний сервис привела к потере бдительности — вы перешли по ней позже и оставили данные.', TRUE, 'red'),
    (32, 4, 'Вы поверили фальшивому уведомлению об «ошибке габаритов» и перешли на фишинговый сайт логистической службы.', TRUE, 'red'),
    (33, 4, 'Вы отказались от сомнительного оформления, но согласились на прямой перевод предоплаты за доставку незнакомцу. Деньги утеряны.', TRUE, 'red'),
    (34, 4, 'Вы успешно распознали обман на последнем шаге и заблокировали продавца. Деньги и карта в безопасности.', TRUE, 'green'),
    (35, 4, 'Испугавшись угроз и «отмены сделки», вы ввели данные карты на поддельном сайте. Сбережения списаны мошенниками.', TRUE, 'red'),
    (36, 4, 'Вы вовремя прервали диалог после первых же угроз со стороны продавца. Безопасность сохранена.', TRUE, 'green')
    ON CONFLICT (id) DO UPDATE SET
    message_text = EXCLUDED.message_text,
                            is_final = EXCLUDED.is_final,
                            final_status = EXCLUDED.final_status;

