-- Вставка вариантов ответов (Options)
INSERT INTO scenario_options (from_node_id, to_node_id, message_text, feedback_text, how_to_recognize_in_life, status)
VALUES
    -- Опции сценария 1
    (1, 2, 'Да, состояние идеальное. Оформляйте доставку в приложении.', 'Отличное начало! Вы переводите покупателя на официальный способ доставки.', 'Мошенники часто пытаются увести диалог в сторонние мессенджеры. Всегда настаивайте на оформлении внутри официального приложения.', 'green'),
    (1, 4, 'Только личная встреча, доставкой не отправляю.', 'Вы отказались от доставки. Попробуйте пройти сценарий заново, чтобы отработать механику безопасной сделки в онлайне.', 'В реальной жизни личная встреча — это безопасный, но ограничивающий продажи шаг. Платформенная доставка безопасна, если соблюдать правила сервиса.', 'red'),
    (2, 5, 'Для доставки почта не нужна, всё оформляется внутри площадки.', 'Супер! Вы вовремя распознали фишинг и не выдали свои контактные данные.', 'Платформа никогда не требует email продавца для оформления доставки. Это типичная уловка, чтобы отправить вам поддельное письмо с фишинговой ссылкой.', 'green'),
    (2, 3, 'Да, конечно, вот моя почта: my.email@gmail.com', 'Рискованный шаг! Передача email — первый шаг к потере средств.', 'Злоумышленники просят электронную почту, чтобы отправить фальшивое уведомление от имени "техподдержки" с требованием ввести данные карты.', 'yellow'),
    (3, 6, 'Пожаловаться в поддержку платформы на подозрительного покупателя', 'Хорошо, что вы не стали переходить по ссылкам из письма! Вы вовремя остановились.', 'Если собеседник давит на срочность и заставляет переходить по подозрительным ссылкам из писем — немедленно блокируйте его и жалуйтесь в поддержку платформы.', 'yellow'),
    (3, 7, 'Перейти по кнопке "Получить средства" в письме', 'Вы перешли на поддельный сайт. Это неизбежно приведет к компрометации данных карты и краже денег.', 'Никогда не вводите данные своей карты (особенно CVC-код и баланс) для "получения" средств. Настоящие маркетплейсы зачисляют деньги на привязанную карту автоматически.', 'red'),

    -- Опции сценария 2
    (8, 9, 'Поддержка Avito не запрашивает коды из смс. Не называю код и проверяю статус заказа в самом приложении', 'Верно! Реальная поддержка работает только внутри приложения и никогда не запрашивает коды подтверждения по переписке.', 'Любая просьба продиктовать код из смс — почти всегда попытка получить доступ к вашему аккаунту или деньгам, даже если её оформляют как "техническую процедуру".', 'green'),
    (8, 12, 'Хорошо, вот код: 7391', 'Вы передали код подтверждения мошеннику. Скорее всего, с его помощью была выполнена операция от вашего имени, а настоящий покупатель никакого перевода не делал.', 'Код из смс — это цифровая подпись, подтверждающая действие в приложении. Отдавая его, вы буквально расписываетесь за то, что делает мошенник.', 'red'),
    (9, 10, 'Подтверждение операций всегда происходит внутри приложения, без переходов по ссылкам из чата. Не перехожу и сообщаю о подозрительном аккаунте в поддержку', 'Отлично! Домен вне официального приложения — уже достаточный повод не переходить по ссылке.', 'Официальные страницы Avito открываются только из самого приложения или проверенного адреса avito.ru — любые "партнёрские" и "для продавцов" ссылки из чата почти всегда поддельные.', 'green'),
    (9, 13, 'Хорошо, перехожу по ссылке и подтверждаю там', 'Страница оказалась подделкой под интерфейс Avito. Введённые данные аккаунта достались мошенникам.', 'Фишинговые копии страниц продавца выглядят почти неотличимо от настоящих — единственная надёжная защита — никогда не переходить по ссылкам, присланным в переписке.', 'red'),
    (10, 14, 'Поддержка Avito работает только через официальный чат в приложении и не запрашивает коды из смс по телефону — не звоню и не называю данные, пишу в поддержку через приложение', 'Отлично! Вы устояли перед всеми тремя попытками — код, ссылка, звонок — и ни разу не поддались давлению и угрозам.', 'Угроза блокировки аккаунта — стандартный приём давления. Настоящая поддержка не звонит с номеров, полученных от собеседника по сделке, и никогда не спрашивает коды из смс по телефону.', 'green'),
    (10, 11, 'Звоню по указанному номеру и диктую код из смс, объяснив, что просто хочу получить деньги за заказ', 'Даже один переданный код из смс достаточен, чтобы мошенники получили доступ к аккаунту или провели операцию от вашего имени — восстановиться после этого уже не получится.', 'Код из смс всегда подтверждает конкретное действие — вход, привязку карты или списание. Называть его нельзя никому и ни при каких обстоятельствах, даже по телефону и даже "только один раз".', 'red'),

    -- Опции сценария 3
    (15, 16, 'Никакие сторонние партнерские сайты использовать не буду. Покупаю только через официальное приложение.', 'Правильно! Ссылки на сторонние «партнерские» магазины — это фишинговые клоны.', 'Сторонние домены, маскирующиеся под маркетплейс — главный признак фишинга.', 'green'),
    (15, 22, 'Хорошо, давайте перейдем по ссылке и купим там подешевле, раз в приложении ошибка.', 'Сайт оказался точной копией платформы. Ваши деньги и данные карты утекли мошенникам.', 'Переход по ссылкам из чата на «зеркала» и «партнерские сайты» ведет к краже средств.', 'red'),
    (16, 20, 'Хорошо, давайте я переведу деньги напрямую вам на карту, раз трек-номер уже есть.', 'Отказ от безопасной сделки в пользу перевода на карту лишает вас любых гарантий.', 'Прямой перевод незнакомцу — это добровольная передача денег без возможности возврата.', 'red'),
    (16, 17, 'Прямой перевод на карту тоже не подходит. Только официальная безопасная сделка.', 'Верно! Вы продолжаете настаивать на правилах площадки.', 'Настойчивое требование продавца обойти защиту платформы — повод прервать сделку.', 'green'),
    (17, 19, 'Никаких курьеров с наличными в обход приложения. Либо сделка через сервис, либо отменяем заказ.', 'Отлично! Вы успешно прошли все ловушки мошенника и защитили свои деньги.', 'Отказ от сомнительных схем доставки защищает от большинства видов мошенничества.', 'green'),
    (17, 21, 'Хорошо, давайте передам наличные курьеру при встрече.', 'Вы согласились на нерегулируемую схему с наличными вне сервиса и потеряли деньги.', 'Передача наличных курьерам "на руки" без чеков и платформы не дает никаких гарантий.', 'red'),
    (17, 18, 'Хорошо, раз курьер едет, давайте оформим трекинг через курьерскую службу.', 'Вы согласились на стороннюю логистику, и мошенник перешел к финальному шагу обмана.', 'Согласие на «удобные» альтернативные способы доставки часто приводит к фишингу.', 'yellow'),
    (18, 23, 'Никаких проверочных нулевых платежей на сторонних сайтах делать не буду. Отменяю покупку!', 'Прекрасно! Вы вовремя распознали фишинговую страницу оплаты перед самым вводом данных.', 'Требование «подтвердить карту» или внести «проверочный платеж» на внешнем ресурсе — 100% скам.', 'green'),
    (18, 22, 'Ладно, подтверждаю нулевой платеж, раз курьер уже у двери.', 'Страница списала полную сумму вместо «проверки». Данные вашей карты скомпрометированы.', 'Под видом «проверки карты» мошенники списывают деньги или подключают автоплатежи.', 'red'),

    -- Опции сценария 4
    (24, 25, 'Оформление доставки только через официальное приложение платформы. Никаких сторонних сервисов.', 'Верно! Продавцы часто объясняют переход на внешние сайты «особенностями товара» (хрупкость, габариты), но это всегда риск.', 'Официальная доставка платформы сама предоставляет необходимые инструкции, трекинг и гарантии безопасности.', 'green'),
    (24, 32, 'Хорошо, давайте перейдем на сайт «СпецБайк», раз это нужно для безопасной упаковки.', 'Сайт оказался подделкой с реалистичным калькулятором габаритов рамы. Данные карты скомпрометированы.', 'Мошенники создают детализированные сайты-имитации транспортных служб под конкретные категории товаров.', 'red'),
    (25, 26, 'Отслеживать буду в приложении. Подожду отправку послезавтра.', 'Отлично! Вы отказались от предложенных ссылок, но продавец продолжает давление.', 'Продавцы часто генерируют выдуманные «сбои», когда понимает, что вы отказываетесь от фишинга.', 'green'),
    (25, 30, 'Спасибо, сторонние ссылки мне не нужны. Только приложение.', 'Отлично! Вы проигнорировали попытку оставить лазейку для перехода на фишинговый сайт.', 'Предложение сохранить стороннюю ссылку «на всякий случай» — расчет на то, что покупатель ослабит бдительность.', 'green'),
    (25, 31, 'Хорошо, сохраню ссылку в блокноте, вдруг на платформе правда зависнет трекинг.', 'Оставленная «на потом» ссылка создает ложное чувство безопасности — позже вы можете случайно перейти по ней.', 'Никогда не сохраняйте ссылки на сторонние вспомогательные сервисы, присланные продавцом в чате.', 'yellow'),
    (26, 27, 'Никаких сторонних сайтов. Если приложение отклоняет, давайте искать альтернативу внутри платформы.', 'Вы устояли перед историей о габаритах, и продавец перешел к попытке забрать деньги прямым переводом.', 'Если одна схема увода на фишинг не сработала, мошенник часто меняет тактику на "предоплату".', 'green'),
    (26, 32, 'Ладно, раз поддержка отклонила, давайте перейдем на их сайт и оформим там.', 'Вы поверили выдуманной истории о сбое и ввели данные на мошенническом ресурсе.', 'Настоящая поддержка маркетплейсов никогда не перенаправляет пользователей на сторонние шлюзы для оплаты.', 'red'),
    (27, 28, 'Предоплату на карту не перевожу. Либо отправка курьером сервиса, либо отмена.', 'Верно! Продавец переходит к жесткому эмоциональному прессингу.', 'Переход на открытые угрозы и манипуляции срочностью — последний шаг перед срывом мошеннической схемы.', 'yellow'),
    (27, 33, 'Хорошо, давайте переведу предоплату за доставку вам на карту напрямую.', 'Прямой перевод незнакомцу лишает вас защиты платформы. Деньги ушли, а велосипед не отправлен.', 'Любое требование перевести деньги напрямую в обход официальных счетов площадки ведет к потере средств.', 'red'),
    (27, 36, 'Никаких предоплат на карту. Я отменяю заказ.', 'Отлично! Вы пресекли попытку перевести расчеты в неконтрорируемую зону и завершили диалог.', 'Отказ от прямых переводов — главный щит против большинства схем мошенничества.', 'green'),
    (28, 34, 'Жаловаться не запрещено. Платить 350 рублей на стороннем сайте не буду, отменяю заказ!', 'Идеально! Вы выдержали жесткий эмоциональный прессинг и не потеряли деньги.', 'Угрозы «жалобами», «блокировками» и «штрафами» создаются специально, чтобы вы действовали в спешке.', 'green'),
    (28, 35, 'Ладно, уговорили, сейчас быстренько оплачу 350 рублей, чтобы не портить рейтинг.', 'Паника поддалась на уловку мошенника. Карта скомпрометирована, со счета списаны все деньги.', 'Требование доплатить мелкую сумму («за сборку», «страховку») на внешнем ресурсе — ловушка для кражи данных карты.', 'red');

